-- 축구 용어 사전 초기 데이터. 다시 넣으면 같은 slug 의 항목을 덮어쓴다.
insert into public.football_glossary (slug, term, english, category, sort, body) values
-- 경기 규칙
('offside', '오프사이드', 'Offside', '경기 규칙', 10, $g$동료가 공을 차는 순간 공격 선수가 상대 진영에서 공과 뒤에서 두 번째 수비수보다 골라인에 더 가까이 있고, 그 상태로 플레이에 관여하면 선언되는 반칙입니다. 위치만으로는 반칙이 아니라 "관여"가 있어야 한다는 점이 핵심이라, 같은 장면을 두고도 해석이 갈리곤 합니다. 자세한 기준은 <a href="/articles/offside-var">오프사이드와 VAR</a> 칼럼에 정리했습니다.$g$),
('var', 'VAR', 'Video Assistant Referee', '경기 규칙', 20, $g$영상으로 판정을 돕는 비디오 판독 심판입니다. 골, 페널티킥, 즉시 퇴장, 선수 오인 네 가지 상황에서만 개입하고, "명백하고 분명한 오심"일 때만 주심에게 알립니다. VAR이 모든 장면을 바로잡는 장치가 아니라 큰 실수를 막는 안전망이라는 점을 알고 보면 판정에 대한 불만이 조금은 줄어듭니다.$g$),
('goal-line-technology', '골라인 판독 기술', 'Goal-line Technology', '경기 규칙', 30, $g$공 전체가 골라인을 넘었는지 카메라로 판단해 1초 안에 주심의 시계로 알려주는 기술입니다. 공이 라인에 조금이라도 걸쳐 있으면 골이 아니며, 사람의 눈으로는 판단하기 어려운 장면을 기계가 맡는 대표적인 사례입니다.$g$),
('penalty-kick', '페널티킥', 'Penalty Kick', '경기 규칙', 40, $g$수비 팀이 자기 페널티 지역 안에서 직접 프리킥에 해당하는 반칙을 했을 때 주어지는 킥으로, 11m 거리에서 골키퍼와 일대일로 찹니다. 성공률은 보통 75~80% 안팎으로 알려져 있어 "넣어야 본전"이라는 말이 나옵니다. 득점 순위의 PK 항목을 보면 어떤 선수가 페널티킥으로 골을 쌓았는지 알 수 있습니다.$g$),
('indirect-free-kick', '간접 프리킥', 'Indirect Free Kick', '경기 규칙', 50, $g$찬 공이 다른 선수에게 한 번 닿아야 골로 인정되는 프리킥입니다. 오프사이드, 위험한 플레이, 골키퍼가 동료의 의도적인 백패스를 손으로 잡은 경우 등에 주어지며, 주심이 한 손을 위로 들어 표시합니다.$g$),
('advantage', '어드밴티지', 'Advantage', '경기 규칙', 60, $g$반칙을 당한 팀이 그대로 공격을 이어가는 것이 더 유리할 때 주심이 경기를 멈추지 않고 진행시키는 규칙입니다. 두 팔을 앞으로 뻗는 동작으로 표시하며, 반칙한 선수에게는 다음 경기 중단 때 경고를 줄 수 있습니다. 좋은 주심일수록 어드밴티지를 잘 살린다는 평가를 받습니다.$g$),
('handball', '핸드볼 반칙', 'Handball', '경기 규칙', 70, $g$손이나 팔(겨드랑이 아래부터)로 공을 건드린 반칙입니다. 팔을 움직여 몸을 부자연스럽게 크게 만든 경우가 주요 판단 기준이며, 공격 선수의 손에 맞고 바로 들어간 골은 우연이라도 인정되지 않습니다. 규칙 문구가 자주 바뀌어 팬들이 가장 헷갈려 하는 규칙 가운데 하나입니다.$g$),
('yellow-card-accumulation', '경고 누적', 'Yellow Card Accumulation', '경기 규칙', 80, $g$한 경기에서 경고 두 장을 받으면 퇴장이고, 시즌 동안 경고가 일정 수 쌓이면 다음 경기에 출장 정지를 받습니다. 누적 기준은 리그와 대회마다 다릅니다. 순위 경쟁이 치열한 시즌 막판에 핵심 선수가 경고 누적으로 빠지면 전력 공백이 생각보다 크게 드러납니다.$g$),
('stoppage-time', '추가 시간', 'Stoppage Time', '경기 규칙', 90, $g$선수 교체, 부상 치료, VAR 확인, 골 세리머니 등으로 흘려보낸 시간을 전·후반 끝에 더하는 시간입니다. 2022 카타르 월드컵 이후 실제로 멈춘 시간을 더 정확하게 반영하는 추세라 추가 시간이 10분 가까이 나오는 경기도 흔해졌습니다. 늦은 시간대 골이 늘어난 이유 가운데 하나로 꼽힙니다.$g$),
('extra-time', '연장전', 'Extra Time', '경기 규칙', 100, $g$토너먼트에서 정규 시간 90분 동안 승부가 나지 않았을 때 치르는 전·후반 15분씩 30분의 추가 경기입니다. 리그 경기에는 연장전이 없습니다. 토리코리 경기 결과의 "연장" 표시는 이 30분까지 치른 경기라는 뜻입니다.$g$),
('penalty-shootout', '승부차기', 'Penalty Shootout', '경기 규칙', 110, $g$연장전까지 비겼을 때 두 팀이 다섯 명씩 번갈아 페널티킥을 차서 승자를 정하는 방식입니다. 다섯 명씩 차고도 같으면 한 명씩 더 찹니다. 공식 기록에서 승부차기 골은 경기 득점에 포함하지 않으므로, 토리코리 스코어 칸에는 연장전까지의 골만 표시하고 승부차기 결과는 따로 적습니다.$g$),
('goalkeeper-eight-seconds', '골키퍼 8초 규칙', 'Eight-second Rule', '경기 규칙', 120, $g$골키퍼가 손으로 공을 잡은 뒤 8초 안에 놓아야 하는 규칙입니다. 2025-26 시즌부터는 이를 어기면 간접 프리킥 대신 상대에게 코너킥을 주도록 바뀌었습니다. 시간을 끄는 행위를 실제로 막기 위해 벌칙을 더 무겁게 만든 사례입니다.$g$),
-- 기록 · 통계
('points', '승점', 'Points', '기록 · 통계', 10, $g$리그 순위를 정하는 기본 점수로, 이기면 3점, 비기면 1점, 지면 0점입니다. 1990년대 중반 대부분의 리그가 승리 2점에서 3점으로 바꾸면서 무승부보다 승리를 노리는 경기 운영이 늘었습니다.$g$),
('goal-difference', '골득실', 'Goal Difference', '기록 · 통계', 20, $g$넣은 골에서 내준 골을 뺀 값입니다. 승점이 같을 때 순위를 가르는 가장 흔한 기준이지만, 라리가와 세리에 A처럼 해당 팀 간 맞대결 성적을 먼저 보는 리그도 있습니다. 골득실은 운이 섞인 승점보다 팀의 실제 전력을 더 잘 보여준다는 평가를 받습니다.$g$),
('points-per-game', '경기당 승점', 'Points Per Game', '기록 · 통계', 30, $g$얻은 승점을 치른 경기 수로 나눈 값입니다. 경기 수가 서로 다른 팀이나 리그를 공정하게 비교할 수 있습니다. 38경기 리그 기준 2.2 이상이면 우승권, 1.0 안팎이면 강등권으로 보는 것이 대략적인 기준입니다. 자세한 활용법은 <a href="/articles/points-per-game">경기당 승점 칼럼</a>에 있습니다.$g$),
('clean-sheet', '클린시트', 'Clean Sheet', '기록 · 통계', 40, $g$한 경기에서 한 골도 내주지 않은 것을 말합니다. 골키퍼와 수비진의 성적을 평가하는 대표 지표이며, 토리코리 팀 분석의 "무실점"이 바로 이 기록입니다. 무실점이 많은데 순위가 낮다면 수비보다 공격에 문제가 있는 팀일 가능성이 큽니다.$g$),
('hat-trick', '해트트릭', 'Hat-trick', '기록 · 통계', 50, $g$한 선수가 한 경기에서 세 골을 넣는 것입니다. 한 경기 두 골은 "멀티골" 또는 영어로 "브레이스"라고 부르고, 오른발·왼발·머리로 한 골씩 넣으면 "퍼펙트 해트트릭"이라고 합니다. 해트트릭을 한 선수가 경기 공을 기념으로 가져가는 전통이 있습니다.$g$),
('assist', '도움', 'Assist', '기록 · 통계', 60, $g$골로 이어진 마지막 패스를 한 선수에게 주는 기록입니다. 수비수에게 맞고 굴절된 경우나 페널티킥을 얻어낸 경우를 도움으로 볼지는 기록 주체마다 기준이 조금씩 달라, 같은 선수의 도움 수가 사이트마다 다르게 나오기도 합니다.$g$),
('own-goal', '자책골', 'Own Goal', '기록 · 통계', 70, $g$수비 선수가 자기 팀 골문에 넣은 골입니다. 상대 팀 득점으로 기록되지만 개인 득점 기록에는 누구에게도 들어가지 않습니다. 슈팅이 수비에 맞고 굴절된 경우 원래 슈팅이 골문으로 향하고 있었다면 슈팅한 선수의 골로 인정하는 것이 일반적입니다.$g$),
('expected-goals', '기대득점 (xG)', 'Expected Goals', '기록 · 통계', 80, $g$슈팅 위치, 각도, 슈팅 방식 등을 바탕으로 그 슈팅이 골이 될 확률을 0~1 사이 값으로 나타낸 지표입니다. 한 경기의 xG를 모두 더하면 "평균적인 선수라면 몇 골을 넣었을 기회였는가"를 알 수 있습니다. 실제 득점이 xG보다 한참 많은 팀은 결정력이 좋거나 운이 따랐다는 뜻이라, 시즌 후반에 득점 페이스가 떨어지는 경우가 많습니다.$g$),
('over-2-5', '2.5골 오버', 'Over 2.5 Goals', '기록 · 통계', 90, $g$두 팀 골을 합쳐 3골 이상 나온 경기를 말합니다. 골이 0.5 단위로 나올 수 없으니 "2.5골보다 많다"는 뜻입니다. 유럽 주요 리그에서는 대략 절반 안팎의 경기가 여기에 해당해, 한 팀의 오버 비율이 이보다 높으면 공수 모두 열린 경기를 자주 하는 팀으로 볼 수 있습니다.$g$),
('btts', '양팀 득점', 'Both Teams To Score', '기록 · 통계', 100, $g$두 팀이 모두 한 골 이상 넣은 경기를 말합니다. 영어 약자로 BTTS라고 부릅니다. 무실점 비율과 무득점 비율이 모두 낮은 팀일수록 양팀 득점 비율이 높게 나옵니다.$g$),
('form', '폼', 'Form', '기록 · 통계', 110, $g$최근 몇 경기의 성적 흐름을 말합니다. 보통 최근 5경기의 승·무·패를 W, D, L로 표시합니다. 시즌 전체 순위보다 "요즘 분위기"를 보여주지만, 5경기는 표본이 작아 일정의 난이도에 크게 좌우된다는 점을 함께 생각해야 합니다.$g$),
('double', '더블', 'Double', '기록 · 통계', 120, $g$한 시즌에 리그와 국내 컵대회를 함께 우승하는 것을 말합니다. 같은 시즌 한 팀을 상대로 홈과 원정 두 경기를 모두 이기는 것도 "더블을 거뒀다"고 표현합니다.$g$),
('treble', '트레블', 'Treble', '기록 · 통계', 130, $g$한 시즌에 리그, 국내 컵대회, 유럽 챔피언스리그를 모두 우승하는 것입니다. 유럽 축구에서 가장 어려운 업적으로 꼽히며, 지금까지 이룬 클럽이 손에 꼽을 정도로 적습니다.$g$),
('unbeaten-run', '무패', 'Unbeaten Run', '기록 · 통계', 140, $g$지지 않고 이어가는 연속 경기 기록입니다. 무승부도 포함하므로 연승과는 다릅니다. 토리코리 라운드 리뷰의 "이어지는 기록"에서 각 리그의 연승, 무패, 연패, 무승 기록을 확인할 수 있습니다.$g$),
-- 대회 · 제도
('promotion-relegation', '승강제', 'Promotion and Relegation', '대회 · 제도', 10, $g$1부 리그 하위 팀이 2부로 내려가고 2부 상위 팀이 1부로 올라오는 제도입니다. 유럽 축구의 가장 큰 특징으로, 시즌 막판 하위권 경기도 우승 경쟁만큼 치열해지는 이유입니다. 1부 리그에서 받는 중계권 수입이 워낙 커서 강등은 구단 재정에 큰 타격이 됩니다.$g$),
('relegation-playoff', '승강 플레이오프', 'Relegation Play-off', '대회 · 제도', 20, $g$1부 리그 하위 팀과 2부 리그 상위 팀이 홈·원정 두 경기로 다음 시즌 1부 자리를 다투는 경기입니다. 분데스리가와 리그 1은 16위 팀이 이 경기를 치릅니다. 토리코리 순위표에서는 강등 플레이오프 자리를 따로 색 막대로 표시합니다.$g$),
('league-phase', '리그 페이즈', 'League Phase', '대회 · 제도', 30, $g$2024-25 시즌부터 챔피언스리그, 유로파리그, 컨퍼런스리그가 조별리그 대신 쓰는 방식입니다. 36개 팀이 하나의 순위표에 들어가 서로 다른 상대와 경기하고, 1~8위는 16강 직행, 9~24위는 플레이오프, 25위 아래는 탈락합니다. 자세한 내용은 <a href="/articles/ucl-league-phase">리그 페이즈 칼럼</a>에 있습니다.$g$),
('away-goals-rule', '원정 다득점 원칙', 'Away Goals Rule', '대회 · 제도', 40, $g$홈·원정 두 경기 합계가 같을 때 원정에서 더 많은 골을 넣은 팀이 이기는 규칙이었습니다. UEFA 대회에서는 2021-22 시즌부터 폐지되어, 이제는 합계가 같으면 바로 연장전과 승부차기로 넘어갑니다. 원정팀이 수비적으로만 나서는 경향을 줄이려는 변화였습니다.$g$),
('uefa-coefficient', 'UEFA 계수', 'UEFA Coefficient', '대회 · 제도', 50, $g$최근 다섯 시즌 동안 유럽대항전에서 거둔 성적을 점수로 합산한 순위입니다. 나라별 계수는 그 나라 리그가 받는 챔피언스리그 진출권 수를 정하고, 클럽별 계수는 추첨 포트 배정에 쓰입니다. 자국 리그 팀들이 유럽대항전에서 오래 살아남을수록 다음 시즌 진출권이 늘어나는 구조입니다.$g$),
('european-performance-spot', '유럽 성적 보너스', 'European Performance Spot', '대회 · 제도', 60, $g$한 시즌 유럽대항전 성적이 가장 좋았던 두 나라가 다음 시즌 챔피언스리그 진출권을 하나씩 더 받는 제도로, 2024-25 시즌부터 시작됐습니다. 이 보너스를 받은 리그에서는 리그 5위도 챔피언스리그에 나갈 수 있습니다.$g$),
('derby', '더비', 'Derby', '대회 · 제도', 70, $g$같은 도시나 가까운 지역 라이벌끼리의 경기를 말합니다. 맨체스터 더비, 밀라노 더비, 마드리드 더비처럼 도시 이름을 붙여 부르며, 순위와 상관없이 팬들에게는 한 시즌 가장 중요한 경기로 꼽힙니다. 지역이 아닌 전통의 라이벌전은 스페인의 "엘 클라시코"처럼 따로 이름이 붙기도 합니다.$g$),
('boxing-day', '박싱데이', 'Boxing Day', '대회 · 제도', 80, $g$크리스마스 다음 날인 12월 26일을 말하며, 잉글랜드 축구는 이날 전통적으로 경기를 치릅니다. 연말연시에 경기가 몰려 선수단이 얇은 팀은 이 시기에 순위가 크게 흔들리곤 합니다. 반대로 분데스리가는 이 시기에 겨울 휴식기를 둡니다.$g$),
('fifty-plus-one', '50+1 규정', '50+1 Rule', '대회 · 제도', 90, $g$독일 구단은 회원(팬)이 의결권의 과반을 가져야 한다는 규정입니다. 외부 투자자가 구단을 마음대로 사고팔지 못하게 해 팬 문화와 저렴한 티켓 가격을 지켜온 바탕으로 평가받습니다. 기업이 오랫동안 지원해 온 레버쿠젠, 볼프스부르크 등 일부 구단은 예외로 인정됩니다.$g$),
('international-break', 'A매치 휴식기', 'International Break', '대회 · 제도', 100, $g$국가대표 경기 일정 때문에 클럽 리그가 쉬는 기간입니다. 한 시즌에 몇 차례 있으며, 이 기간 뒤에는 장거리 이동과 부상으로 컨디션이 떨어진 대표 선수가 많은 팀이 고전하는 경우가 종종 있습니다.$g$),
-- 전술 · 포지션
('formation', '포메이션', 'Formation', '전술 · 포지션', 10, $g$골키퍼를 뺀 10명의 선수를 수비·미드필더·공격 순으로 배치한 숫자입니다(예: 4-3-3, 3-5-2). 다만 현대 축구에서는 공을 가졌을 때와 잃었을 때 대형이 크게 바뀌기 때문에, 중계 화면에 나오는 포메이션은 출발점일 뿐 실제 경기 모습과 다른 경우가 많습니다.$g$),
('back-three', '스리백', 'Back Three', '전술 · 포지션', 20, $g$중앙 수비수 세 명을 두는 수비 형태입니다. 좌우 윙백이 높이 올라가 공격에 가담하고, 수비할 때는 다섯 명이 한 줄로 서는 "파이브백"이 되기도 합니다. 세리에 A에서 특히 오래 사랑받아 온 형태입니다.$g$),
('gegenpressing', '게겐프레싱', 'Gegenpressing', '전술 · 포지션', 30, $g$공을 빼앗긴 직후 곧바로 여러 명이 달려들어 다시 빼앗는 전술입니다. 상대가 공격을 전개하기 전 수비 대형이 흐트러진 순간을 노리는 것으로, 독일어로 "역압박"이라는 뜻입니다. 체력 소모가 커서 로테이션과 선수단 깊이가 뒷받침돼야 시즌 내내 유지할 수 있습니다.$g$),
('high-line', '하이 라인', 'High Defensive Line', '전술 · 포지션', 40, $g$수비 라인을 하프라인 가까이 끌어올려 선수 간 간격을 좁히는 운영입니다. 상대를 좁은 공간에 가두고 오프사이드를 유도할 수 있지만, 뒷공간을 파고드는 빠른 공격수에게 한 번에 무너질 위험이 있습니다.$g$),
('low-block', '로우 블록', 'Low Block', '전술 · 포지션', 50, $g$수비 라인과 미드필드 라인을 자기 페널티 지역 가까이 내려 공간을 없애는 수비 방식입니다. 전력이 약한 팀이 강팀을 상대로 자주 쓰며, 무실점 경기를 만드는 데 효과적이지만 스스로 골을 넣기는 어려워집니다.$g$),
('build-up', '빌드업', 'Build-up', '전술 · 포지션', 60, $g$골키퍼와 수비수부터 짧은 패스로 공격을 차근차근 만들어 가는 과정입니다. 상대의 압박을 풀어낼 수 있으면 경기를 지배할 수 있지만, 자기 진영에서 공을 빼앗기면 곧바로 실점 위기로 이어집니다.$g$),
('counter-attack', '역습', 'Counter-attack', '전술 · 포지션', 70, $g$상대 공격을 막아낸 뒤 상대 수비가 정비되기 전에 빠르게 전진해 골을 노리는 공격입니다. 점유율이 낮아도 골을 넣을 수 있는 방법이라, 점유율 수치만으로 경기 내용을 판단하면 안 되는 이유이기도 합니다.$g$),
('set-piece', '세트피스', 'Set Piece', '전술 · 포지션', 80, $g$코너킥, 프리킥, 스로인처럼 경기가 멈췄다가 다시 시작되는 상황을 말합니다. 미리 준비한 약속된 움직임이 통하기 쉬워, 전력이 비슷한 팀끼리의 경기에서는 세트피스 한 번이 승부를 가르는 일이 많습니다. 최근에는 세트피스 전담 코치를 두는 구단이 늘었습니다.$g$),
('false-nine', '폴스 나인', 'False Nine', '전술 · 포지션', 90, $g$최전방 공격수(9번) 자리에 선 선수가 중원으로 자주 내려와 공을 받는 역할입니다. 상대 중앙 수비수를 끌어내 그 뒤 공간을 측면 공격수가 파고들게 만드는 것이 목적입니다.$g$),
('inverted-full-back', '인버티드 풀백', 'Inverted Full-back', '전술 · 포지션', 100, $g$측면 수비수가 공격할 때 측면을 따라 올라가지 않고 중앙 미드필더 자리로 들어오는 역할입니다. 중원 숫자를 늘려 빌드업을 안정시키고, 공을 잃었을 때 역습을 막는 데 도움이 됩니다.$g$),
('box-to-box', '박스 투 박스', 'Box-to-box Midfielder', '전술 · 포지션', 110, $g$자기 페널티 박스에서 상대 페널티 박스까지 쉼 없이 오가며 공격과 수비를 모두 돕는 미드필더를 말합니다. 활동량과 체력이 가장 큰 무기입니다.$g$),
('sweeper-keeper', '스위퍼 키퍼', 'Sweeper-keeper', '전술 · 포지션', 120, $g$페널티 지역 밖까지 나와 수비 뒷공간을 정리하고, 발로 빌드업에도 참여하는 골키퍼입니다. 하이 라인을 쓰는 팀일수록 골키퍼의 이런 능력이 중요해집니다.$g$),
-- 이적 · 구단
('transfer-window', '이적시장', 'Transfer Window', '이적 · 구단', 10, $g$구단이 다른 구단 선수를 영입해 등록할 수 있는 기간입니다. 유럽 주요 리그는 시즌 전 여름과 1월 겨울 두 번 열립니다. 겨울 이적시장은 짧고 선수를 내주려는 구단이 적어 큰 이적이 드문 편입니다.$g$),
('bosman-ruling', '보스만 판결', 'Bosman Ruling', '이적 · 구단', 20, $g$1995년 유럽사법재판소가 계약이 끝난 선수는 이적료 없이 자유롭게 팀을 옮길 수 있다고 판결한 사건입니다. 이후 계약 만료 선수를 영입하는 "자유계약(FA) 이적"이 흔해졌고, 구단들은 선수와 계약 기간을 길게 잡기 시작했습니다.$g$),
('loan', '임대', 'Loan', '이적 · 구단', 30, $g$선수의 소속은 유지한 채 일정 기간 다른 구단에서 뛰게 하는 방식입니다. 젊은 선수에게 출전 기회를 주거나 연봉 부담을 나누려고 많이 씁니다. 임대 후 완전 영입 옵션이나 의무 조항이 붙는 경우도 많습니다.$g$),
('release-clause', '바이아웃 조항', 'Release Clause', '이적 · 구단', 40, $g$정해진 금액을 내면 소속 구단의 동의 없이 선수를 데려갈 수 있다는 계약 조항입니다. 스페인에서는 모든 선수 계약에 이 조항을 넣어야 해서, 라리가 스타 선수들의 바이아웃 금액이 수억 유로에 이르기도 합니다.$g$),
('financial-rules', '재정 규정', 'Financial Sustainability Rules', '이적 · 구단', 50, $g$구단이 벌어들이는 돈보다 과하게 지출하지 못하도록 막는 규정입니다. UEFA는 선수단 관련 비용을 수입의 일정 비율(2025-26 시즌부터 70%) 안으로 묶고 있고, 프리미어리그 등 각 리그도 자체 규정을 두고 있습니다. 규정을 어기면 벌금이나 승점 삭감을 받을 수 있어, 순위표에도 영향을 줍니다.$g$),
('homegrown', '홈그로운', 'Homegrown Player', '이적 · 구단', 60, $g$일정 나이 이전에 자국 리그나 해당 구단에서 일정 기간 훈련한 선수를 말합니다. 프리미어리그와 UEFA 대회는 선수 등록 명단에 홈그로운 선수를 일정 수 이상 넣도록 정하고 있어, 유망주 육성이 성적만큼 중요한 이유가 됩니다.$g$)
on conflict (slug) do update set
  term = excluded.term, english = excluded.english, category = excluded.category, sort = excluded.sort, body = excluded.body;
